INSERT IGNORE INTO `ehr_job_post` (`id`, `job_no`, `title`, `org_id`, `job_type`, `work_city`, `headcount`, `salary_min`, `salary_max`, `education_req`, `experience_req`, `description`, `requirement`, `tags`, `status`, `publish_at`, `close_at`, `sort_no`, `owner_id`, `created_by`, `deleted`, `created_at`, `updated_at`, `org_code`) VALUES (2500000000000000001,'JOB-2026-001','Java 后端工程师',2116787732158066689,'FULL_TIME','西安',2,15000.00,25000.00,'本科','3-5年','1. 负责核心业务系统的服务端设计与开发，保障接口性能与稳定性；\n2. 参与需求评审、技术方案设计、代码评审与线上问题排查；\n3. 持续优化系统架构，沉淀通用组件与技术文档。','1. 本科及以上学历，计算机相关专业，3 年以上 Java 服务端开发经验；\n2. 熟练掌握 Spring Boot / Spring Cloud、MyBatis、MySQL、Redis；\n3. 熟悉分布式系统常见问题与解决方案，有高并发场景经验优先；\n4. 具备良好的沟通协作能力与责任心。','五险一金,双休,弹性工作,年终奖','PUBLISHED','2026-11-09 22:18:10','2027-02-07',10,2119703016825098241,2119703016825098241,0,'2026-11-09 22:18:10','2026-11-15 14:55:58','XC000100010001');
INSERT IGNORE INTO `ehr_job_post` (`id`, `job_no`, `title`, `org_id`, `job_type`, `work_city`, `headcount`, `salary_min`, `salary_max`, `education_req`, `experience_req`, `description`, `requirement`, `tags`, `status`, `publish_at`, `close_at`, `sort_no`, `owner_id`, `created_by`, `deleted`, `created_at`, `updated_at`, `org_code`) VALUES (2500000000000000002,'JOB-2026-002','高级前端工程师',2116787733110173698,'FULL_TIME','北京',1,20000.00,35000.00,'本科','5-10年','1. 负责管理端与门户端前端架构设计、核心功能开发与性能优化；\n2. 建设前端工程化体系，沉淀组件库与研发规范；\n3. 与产品、设计、后端协作，保障交付质量与体验一致性。','1. 本科及以上学历，5 年以上前端开发经验，有中大型项目架构经验；\n2. 精通 Vue 3 / TypeScript，熟悉 Vite、Pinia、Ant Design Vue；\n3. 熟悉浏览器渲染机制、性能优化与前端监控；\n4. 有微前端、可视化或低代码平台经验优先。','五险一金,弹性工作,年终奖,股票期权','PUBLISHED','2026-11-09 22:18:10','2027-02-07',20,2119703016825098241,2119703016825098241,0,'2026-11-09 22:18:10','2026-11-15 14:55:58','XC000100020001');
INSERT IGNORE INTO `ehr_job_post` (`id`, `job_no`, `title`, `org_id`, `job_type`, `work_city`, `headcount`, `salary_min`, `salary_max`, `education_req`, `experience_req`, `description`, `requirement`, `tags`, `status`, `publish_at`, `close_at`, `sort_no`, `owner_id`, `created_by`, `deleted`, `created_at`, `updated_at`, `org_code`) VALUES (2500000000000000003,'JOB-2026-003','产品经理',2116787732598468609,'FULL_TIME','西安',1,15000.00,25000.00,'本科','3-5年','1. 负责 HR / 协同办公方向产品的需求调研、方案设计与迭代规划；\n2. 输出 PRD、原型与验收标准，推动研发、测试按期交付；\n3. 基于数据与用户反馈持续优化产品体验。','1. 本科及以上学历，3 年以上 B 端产品经验，有 HR SaaS 经验优先；\n2. 具备完整的从 0 到 1 产品落地经验，逻辑清晰、文档能力强；\n3. 熟练使用 Axure / Figma 等原型工具；\n4. 具备良好的跨部门沟通与项目推进能力。','五险一金,双休,培训机会,晋升空间','PUBLISHED','2026-11-09 22:18:10','2027-02-07',30,2119703016825098241,2119703016825098241,0,'2026-11-09 22:18:10','2026-11-15 14:55:58','XC000100010002');
INSERT IGNORE INTO `ehr_job_post` (`id`, `job_no`, `title`, `org_id`, `job_type`, `work_city`, `headcount`, `salary_min`, `salary_max`, `education_req`, `experience_req`, `description`, `requirement`, `tags`, `status`, `publish_at`, `close_at`, `sort_no`, `owner_id`, `created_by`, `deleted`, `created_at`, `updated_at`, `org_code`) VALUES (2500000000000000004,'JOB-2026-004','测试开发工程师',2117998407475703810,'FULL_TIME','上海',2,12000.00,20000.00,'本科','1-3年','1. 负责业务系统的功能测试、接口测试与自动化测试建设；\n2. 搭建并维护持续集成流水线，提升回归效率与质量；\n3. 参与线上问题复盘，推动质量改进措施落地。','1. 本科及以上学历，1 年以上测试开发经验；\n2. 熟悉 Java 或 Python，能独立编写自动化测试脚本；\n3. 熟悉 JMeter、Postman 等接口测试工具，了解 MySQL 基本操作；\n4. 有性能测试或持续集成实践经验优先。','五险一金,双休,餐饮补贴,团队氛围','PUBLISHED','2026-11-09 22:18:10','2027-02-07',40,2119703016825098241,2119703016825098241,0,'2026-11-09 22:18:10','2026-11-15 14:55:58','XC000100060002');
INSERT IGNORE INTO `ehr_job_post` (`id`, `job_no`, `title`, `org_id`, `job_type`, `work_city`, `headcount`, `salary_min`, `salary_max`, `education_req`, `experience_req`, `description`, `requirement`, `tags`, `status`, `publish_at`, `close_at`, `sort_no`, `owner_id`, `created_by`, `deleted`, `created_at`, `updated_at`, `org_code`) VALUES (2500000000000000005,'JOB-2026-005','招聘专员',2118305689082163201,'FULL_TIME','广州',1,8000.00,12000.00,'大专','1-3年','1. 负责各招聘渠道的职位发布、简历筛选、面试安排与候选人跟进；\n2. 维护招聘数据与人才库，定期输出招聘进展分析；\n3. 协助优化招聘流程与雇主品牌内容。','1. 大专及以上学历，1 年以上招聘相关经验；\n2. 熟悉主流招聘渠道与面试流程，沟通表达清晰；\n3. 熟练使用 Excel 等办公软件，具备基础数据分析能力；\n4. 工作细致、有耐心，抗压能力强。','五险一金,双休,培训机会,交通补贴','PUBLISHED','2026-11-09 22:18:10','2027-02-07',50,2119703016825098241,2119703016825098241,0,'2026-11-09 22:18:10','2026-11-15 14:55:58','XC000100040001');
